steps.script:
$ErrorActionPreference='Stop'
$o=@{state='pending';version='5cb7181';editorialOnly=$true}
$t=Join-Path $env:TEMP ('TTEditorialGuard-'+[guid]::NewGuid().ToString('N')+'.ps1')
try{
 $live=@(Get-CimInstance Win32_Process -Filter "name='node.exe'"|Where-Object{[string]$_.CommandLine -match '(?:[\\/])(?:Ejecutar|TT-Editorial-Guard)[.]js'})
 if($live.Count){$o.state='deferred_active_editorial';$o.count=$live.Count}
 else{
  $url='https://raw.githubusercontent.com/fabricelop/europapress-rss/5cb71812c7e562ffa4ce0a52ba33a07e712104e7/windows/Reparar-TT-Editorial-20261111.ps1'
  Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $t -TimeoutSec 35
  $src=[IO.File]::ReadAllText($t,[Text.Encoding]::UTF8)
  if(-not $src.Contains('PROJECT_LANDING_HISTORY; NAVIGATE_BOT_OWNED_TAB_HOME') -or -not $src.Contains('const focused=await c.eval(') -or -not $src.Contains('TT_EDITORIAL_SAFE_WRAPPER_V1')){throw 'PINNED_GUARD_MARKER_MISSING'}
  $errors=$null;$tokens=$null
  [Management.Automation.Language.Parser]::ParseFile($t,[ref]$tokens,[ref]$errors)|Out-Null
  if($errors.Count){throw 'GUARD_INSTALLER_SYNTAX_INVALID'}
  & $t -NoDispatch *> $null
  if(-not $?){throw 'GUARD_INSTALLER_FAILED'}
  $guard=Get-Content 'C:\TTiTTulares\TT-Editorial-Guard.js' -Raw
  if(-not $guard.Contains('PROJECT_LANDING_HISTORY; NAVIGATE_BOT_OWNED_TAB_HOME')){throw 'GUARD_NOT_UPDATED'}
  $o.state='installed_verified'
 }
}catch{$o.state='error';$o.reason=([string]$_.Exception.Message).Substring(0,[Math]::Min(160,([string]$_.Exception.Message).Length))}
finally{Remove-Item $t -Force -ErrorAction SilentlyContinue}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
